     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        RatePlanStrategy strategy = RatePlanStrategies.of(request.ratePlan());
    43	        strategy.validate(request, room);
    44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    45	            throw new HotelException(
    46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    47	        }
    48	        Price price = priceCalculator.calculate(request, room);
    49	        return store.add(request, price);
    50	    }
    51	
    52	    public Reservation find(long reservationId) {
    53	        return store.find(reservationId)
    54	                .orElseThrow(() -> new HotelException(
    55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    56	    }
    57	
    58	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    59	    public synchronized Reservation confirm(long reservationId) {
    60	        Reservation reservation = find(reservationId);
    61	        if (reservation.status() != ReservationStatus.PENDING) {
    62	            throw notAllowed(reservation, "confirm");
    63	        }
    64	        reservation.confirmPayment();
    65	        store.update(reservation);
    66	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    67	        emailSender.send(
    68	                reservation.guest().email(),
    69	                "Reserva confirmada - " + HOTEL_NAME,
    70	                confirmationEmailBody(reservation, receipt));
    71	        return reservation;
    72	    }
    73	
    74	    /**
    75	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    76	     * reservation was never paid, so nothing comes back).
    77	     */
    78	    public synchronized Reservation cancel(long reservationId) {
    79	        Reservation reservation = find(reservationId);
    80	        if (reservation.status() != ReservationStatus.PENDING
    81	                && reservation.status() != ReservationStatus.CONFIRMED) {
    82	            throw notAllowed(reservation, "cancel");
    83	        }
    84	        RatePlanStrategy strategy = RatePlanStrategies.of(reservation.ratePlan());
    85	        BigDecimal refund = strategy.calculateRefund(reservation);
    86	        if (reservation.status() == ReservationStatus.PENDING) {
    87	            refund = PriceCalculator.cents(BigDecimal.ZERO);
    88	        }
    89	        reservation.cancel(refund);
    90	        store.update(reservation);
    91	        return reservation;
    92	    }
    93	
    94	    public synchronized Reservation checkIn(long reservationId) {
    95	        Reservation reservation = find(reservationId);
    96	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    97	            throw notAllowed(reservation, "check in");
    98	        }
    99	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   100	        store.update(reservation);
   101	        return reservation;
   102	    }
   103	
   104	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   105	    public synchronized ReservationReceipt checkOut(long reservationId) {
   106	        Reservation reservation = find(reservationId);
   107	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   108	            throw notAllowed(reservation, "check out");
   109	        }
   110	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   111	        store.update(reservation);
   112	        return new ReservationReceipt(reservation, roomOf(reservation));
   113	    }
   114	
   115	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   116	    public ReservationReceipt receiptCopy(long reservationId) {
   117	        Reservation reservation = find(reservationId);
   118	        if (!reservation.isPaid()) {
   119	            throw notAllowed(reservation, "issue a receipt for");
   120	        }
   121	        return new ReservationReceipt(reservation, roomOf(reservation));
   122	    }
   123	
   124	    private Room roomOf(Reservation reservation) {
   125	        return rooms.find(reservation.roomNumber()).orElseThrow();
   126	    }
   127	
   128	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   129	        return "Olá, " + reservation.guest().name() + "!\n\n"
   130	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   131	                + receipt.text() + "\n"
   132	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   133	                + "Até breve!\n";
   134	    }
   135	
   136	    private static HotelException notAllowed(Reservation reservation, String operation) {
   137	        return new HotelException(
   138	                ErrorCode.OPERATION_NOT_ALLOWED,
   139	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   140	    }
   141	}
   142	package hotel.reservations;
   143	
   144	import hotel.rooms.Room;
   145	import java.math.BigDecimal;
   146	import java.math.RoundingMode;
   147	import java.time.LocalDate;
   148	import java.time.Month;
   149	
   150	/**
   151	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   152	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   153	 * (half-even) at every step.
   154	 */
   155	public final class PriceCalculator {
   156	
   157	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   158	
   159	    public Price calculate(NewReservation request, Room room) {
   160	        RatePlanStrategy strategy = RatePlanStrategies.of(request.ratePlan());
   161	        return strategy.calculatePrice(request, room);
   162	    }
   163	
   164	    static BigDecimal nightPrice(Room room, LocalDate night) {
   165	        BigDecimal nightlyRate = room.nightlyRate();
   166	        if (isHighSeason(night)) {
   167	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   168	        }
   169	        return cents(nightlyRate);
   170	    }
   171	
   172	    /** High season: from December 15 to the end of February, and the whole of July. */
   173	    static boolean isHighSeason(LocalDate date) {
   174	        Month month = date.getMonth();
   175	        return month == Month.JANUARY
   176	                || month == Month.FEBRUARY
   177	                || month == Month.JULY
   178	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   179	    }
   180	
   181	    static BigDecimal cents(BigDecimal value) {
   182	        return value.setScale(2, RoundingMode.HALF_EVEN);
   183	    }
   184	}
